import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import {
  getTeacherCourses, getTeacherSubmissions,
  getTeacherPerformance, getTeacherAIContent, approveAIContent
} from '../../api';
import { MetricCard, Badge, Card, SectionTitle, Spinner, difficultyVariant } from '../../components/UI';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { CheckCircle2 } from 'lucide-react';

export default function TeacherDashboard() {
  const { user } = useAuth();
  const [courses,     setCourses]     = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [performance, setPerformance] = useState([]);
  const [aiContent,   setAiContent]   = useState([]);
  const [loading,     setLoading]     = useState(true);
  const [activeCourse, setActiveCourse] = useState(null);

  useEffect(() => {
    Promise.all([
      getTeacherCourses(user.id),
      getTeacherSubmissions(user.id),
      getTeacherAIContent(user.id),
    ]).then(([c, s, ai]) => {
      setCourses(c.data);
      setSubmissions(s.data);
      setAiContent(ai.data);
      if (c.data.length > 0) {
        setActiveCourse(c.data[0].course_id);
        return getTeacherPerformance(user.id, c.data[0].course_id);
      }
    }).then(perf => {
      if (perf) setPerformance(perf.data);
    }).finally(() => setLoading(false));
  }, [user.id]);

  const handleCourseChange = async (courseId) => {
    setActiveCourse(courseId);
    const res = await getTeacherPerformance(user.id, courseId);
    setPerformance(res.data);
  };

  const handleApprove = async (contentId) => {
    await approveAIContent(contentId);
    setAiContent(prev => prev.map(c => c.content_id === contentId ? { ...c, is_approved: 1 } : c));
  };

  if (loading) return <Spinner />;

  const pending = submissions.filter(s => !s.grade);

  return (
    <div className="p-6 max-w-5xl">
      <div className="mb-6">
        <h1 className="text-xl font-medium text-gray-900">{user.name}</h1>
        <p className="text-sm text-gray-400 mt-0.5">Teacher dashboard</p>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
        <MetricCard label="My courses"       value={courses.length} />
        <MetricCard label="Total students"   value={courses.reduce((s, c) => s + (c.student_count || 0), 0)} />
        <MetricCard label="Pending grading"  value={pending.length} />
        <MetricCard label="AI content items" value={aiContent.length} sub={`${aiContent.filter(c => !c.is_approved).length} pending approval`} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Course performance chart */}
        <Card>
          <div className="flex items-center justify-between mb-3">
            <SectionTitle>Class performance</SectionTitle>
            <select
              className="text-xs border border-gray-200 rounded-lg px-2 py-1 text-gray-600 bg-white"
              value={activeCourse || ''}
              onChange={e => handleCourseChange(Number(e.target.value))}
            >
              {courses.map(c => (
                <option key={c.course_id} value={c.course_id}>{c.course_code}</option>
              ))}
            </select>
          </div>
          {performance.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={performance} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
                <XAxis dataKey="topic_name" tick={{ fontSize: 10 }} tickLine={false} axisLine={false}
                  tickFormatter={v => v.length > 10 ? v.slice(0, 10) + '…' : v} />
                <YAxis tick={{ fontSize: 10 }} tickLine={false} axisLine={false} domain={[0, 100]} />
                <Tooltip
                  formatter={(v) => [`${v}%`, 'Avg score']}
                  contentStyle={{ fontSize: 12, borderRadius: 8, border: '0.5px solid #eee' }}
                />
                <Bar dataKey="avg_score" fill="#1a7af0" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <p className="text-sm text-gray-400 py-8 text-center">No progress data yet</p>
          )}
        </Card>

        {/* Submissions table */}
        <Card>
          <SectionTitle>Recent submissions</SectionTitle>
          <div className="flex flex-col divide-y divide-gray-50 overflow-y-auto max-h-64">
            {submissions.slice(0, 8).map(s => (
              <div key={s.submission_id} className="flex items-center justify-between py-2.5 first:pt-0 last:pb-0">
                <div className="min-w-0 mr-2">
                  <p className="text-sm text-gray-800 truncate">{s.student_name}</p>
                  <p className="text-xs text-gray-400 truncate">{s.assignment_title} · {s.course_code}</p>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  {s.grade
                    ? <Badge label={`${s.grade} · ${s.marks_obtained}/${s.total_marks}`} variant="green" />
                    : <Badge label={s.submission_status || 'Pending'} variant={s.submission_status === 'Late' ? 'red' : 'amber'} />
                  }
                </div>
              </div>
            ))}
          </div>
        </Card>

        {/* AI content approval */}
        <Card className="lg:col-span-2">
          <SectionTitle>AI-generated content — pending approval</SectionTitle>
          {aiContent.filter(c => !c.is_approved).length === 0 ? (
            <p className="text-sm text-gray-400">All content approved.</p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {aiContent.filter(c => !c.is_approved).map(c => (
                <div key={c.content_id} className="border border-gray-100 rounded-xl p-3">
                  <div className="flex items-center justify-between mb-2">
                    <div>
                      <span className="text-xs font-medium text-gray-700">{c.topic_name}</span>
                      <span className="text-xs text-gray-400 ml-2">{c.content_type}</span>
                    </div>
                    <Badge label={c.course_code} variant="blue" />
                  </div>
                  <p className="text-xs text-gray-500 mb-3 line-clamp-3">{c.content_text}</p>
                  <button
                    onClick={() => handleApprove(c.content_id)}
                    className="flex items-center gap-1.5 text-xs text-teal-600 font-medium hover:text-teal-800 transition-colors"
                  >
                    <CheckCircle2 size={13} /> Approve
                  </button>
                </div>
              ))}
            </div>
          )}
        </Card>

        {/* My courses */}
        <Card className="lg:col-span-2">
          <SectionTitle>My courses</SectionTitle>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {courses.map(c => (
              <div key={c.course_id} className="border border-gray-100 rounded-xl p-3">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs font-mono text-brand-600">{c.course_code}</span>
                  <Badge label={c.difficulty_level} variant={difficultyVariant(c.difficulty_level)} />
                </div>
                <p className="text-sm font-medium text-gray-800 mb-2">{c.course_name}</p>
                <div className="flex gap-3 text-xs text-gray-400">
                  <span>{c.student_count} students</span>
                  <span>{c.quiz_count} quizzes</span>
                  <span>{c.assignment_count} assignments</span>
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
}
